diff --git a/services/stripe/discounts.ts b/services/stripe/discounts.ts
new file mode 100644
index 0000000..b759d6d
--- /dev/null
+++ b/services/stripe/discounts.ts
@@ -0,0 +1,22 @@
+import type Stripe from 'stripe'
+
+type DiscountWithSource = {
+  source?: {
+    type?: string
+    coupon?: string | Stripe.Coupon | null
+  } | null
+}
+
+export function getSubscriptionCoupon(subscription: Stripe.Subscription): Stripe.Coupon | null {
+  const discounts = (subscription as unknown as { discounts?: unknown[] | null }).discounts ?? []
+
+  for (const discount of discounts) {
+    if (!discount || typeof discount === 'string') continue
+    const source = (discount as DiscountWithSource).source
+    if (source?.type === 'coupon' && source.coupon && typeof source.coupon !== 'string') {
+      return source.coupon
+    }
+  }
+
+  return null
+}
